THEME_INIT = """<script>try{const saved=localStorage.getItem('wpp-theme');document.documentElement.dataset.theme=saved==='light'?'light':'dark'}catch(e){document.documentElement.dataset.theme='dark'}</script>"""
COMMON_JS = """<script>
document.querySelectorAll('[data-theme-toggle]').forEach(b=>{function label(){const light=document.documentElement.dataset.theme==='light';b.querySelector('span').textContent=light?'Тёмная тема':'Светлая тема';b.setAttribute('aria-label',light?'Включить тёмную тему':'Включить светлую тему')}label();b.addEventListener('click',()=>{const t=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=t;try{localStorage.setItem('wpp-theme',t)}catch(e){}document.querySelectorAll('[data-theme-toggle] span').forEach(s=>s.textContent=t==='light'?'Тёмная тема':'Светлая тема');label()})});
async function wppCopy(text,container=document.body){try{await navigator.clipboard.writeText(text);return}catch(e){}const prior=document.activeElement,x=document.createElement('textarea');x.value=text;x.setAttribute('aria-label','Копирование ссылки');x.style.position='fixed';x.style.opacity='0';container.appendChild(x);try{x.focus();x.select();if(!document.execCommand('copy'))throw new Error('Clipboard unavailable')}finally{x.remove();if(prior?.isConnected)prior.focus()}}
function wppCloseDialog(dialog,value=''){if(!dialog||!dialog.open||dialog.dataset.wppClosing==='1')return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced){dialog.close(value);return}dialog.dataset.wppClosing='1';dialog.classList.add('wpp-closing');let done=false;const finish=()=>{if(done)return;done=true;dialog.removeEventListener('transitionend',onEnd);delete dialog.dataset.wppClosing;dialog.classList.remove('wpp-closing');if(dialog.open)dialog.close(value)};const onEnd=e=>{if(e.target===dialog&&e.propertyName==='opacity')finish()};dialog.addEventListener('transitionend',onEnd);setTimeout(finish,260)}
document.addEventListener('cancel',e=>{if(e.target instanceof HTMLDialogElement){e.preventDefault();wppCloseDialog(e.target)}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-copy]');if(b&&!b.disabled){const old=b.innerHTML;b.disabled=true;try{await wppCopy(b.dataset.copy,b.closest('dialog')||document.body);b.textContent=b.classList.contains('icon-btn')?'✓':'✓ Скопировано'}catch(err){b.textContent=b.classList.contains('icon-btn')?'!':'Не удалось скопировать'}finally{setTimeout(()=>{b.innerHTML=old;b.disabled=false},1600)}}const close=e.target.closest('[data-close-dialog]');if(close){const d=close.closest('dialog');wppCloseDialog(d);const frame=d.querySelector('iframe');if(frame){frame.removeAttribute('srcdoc')}}});
document.addEventListener('submit',e=>{const f=e.target.closest('form[data-confirm]');if(f&&!confirm(f.dataset.confirm))e.preventDefault()});
let wppNavigationTimer=0;
    function wppSyncActiveNavigation(){document.querySelectorAll('.topnav a').forEach(link=>{let current=false;try{current=new URL(link.href,location.href).pathname===location.pathname}catch(e){}link.classList.toggle('active',current);link.classList.remove('is-pending')})}
    function wppFinishNavigation(){clearTimeout(wppNavigationTimer);document.documentElement.classList.remove('wpp-navigating');wppSyncActiveNavigation()}
    function wppStartNavigation(link){wppFinishNavigation();document.documentElement.classList.add('wpp-navigating');if(link){document.querySelectorAll('.topnav a.active').forEach(item=>item.classList.remove('active'));link.classList.add('active','is-pending')}wppNavigationTimer=setTimeout(wppFinishNavigation,10000)}
document.addEventListener('click',e=>{const link=e.target.closest('.topnav a,.mini-brand');if(!link||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||link.target)return;let next;try{next=new URL(link.href,location.href)}catch(error){return}if(next.origin!==location.origin)return;if(next.pathname===location.pathname&&next.search===location.search){e.preventDefault();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return}wppStartNavigation(link)});
document.addEventListener('submit',e=>queueMicrotask(()=>{const form=e.target;if(e.defaultPrevented||!(form instanceof HTMLFormElement)||form.target)return;const method=(form.method||'get').toLowerCase();if(method==='get'||method==='post')wppStartNavigation()}));
window.addEventListener('pageshow',wppFinishNavigation);
</script>"""


def qr_attributes(endpoint, name, link, protocols, kind='direct', user_port=None):
    labels={'web':'WEB Proxy','vless':'VLESS XHTTP','hysteria':'Hysteria2','mtproto':'MTProto','awg20':'AWG 2.0','awg31':'AWG 3.1','openflux':'OpenFlux'}
    parsed=urlsplit(link)
    web=protocols==['web']
    openflux=protocols==['openflux']
    telegram=web or protocols==['mtproto']
    host='Импорт профиля' if openflux else parse_qs(parsed.query).get('server',[parsed.hostname or ''])[0] if telegram else parsed.hostname or ''
    port=None if web or openflux or kind=='subscription' else int(parse_qs(parsed.query).get('port',['443'])[0]) if protocols==['mtproto'] else parsed.port or 443
    if protocols and protocols[0] in ('awg20','awg31'):
        match=re.search(r'(?m)^Endpoint\s*=\s*([^:\s]+):(\d+)\s*$',link)
        host=match.group(1) if match else ''
        port=int(match.group(2)) if match else (int(user_port) if user_port else None)
    info={'name':name,'link':link,'protocols':' · '.join(labels.get(p,p) for p in protocols),
          'kind':kind,'host':host,'port':port,'web':telegram,'openflux':openflux}
    return 'data-qr="'+esc(endpoint)+'" data-qr-info="'+esc(json.dumps(info,ensure_ascii=False))+'"'


