    connection_script='''<style>#directFields>.protocol-picker,#directFields>.quick-access-title,#directFields>.quick-access-note,#directFields>.quick-access-grid [data-quick-protocol]{display:none!important}#directFields>.quick-access-grid{display:grid!important;grid-template-columns:minmax(0,1fr)!important}</style><script>(()=>{const select=document.getElementById('connectionTemplate'),form=document.getElementById('createClientForm');if(!select||!form)return;let applying=false;function selectConnection(){const option=select.selectedOptions[0],protocol=option?.dataset.protocol;if(!protocol)return;applying=true;const radio=form.querySelector('[name=direct_protocol][value="'+protocol+'"]');if(radio){radio.checked=true;radio.dispatchEvent(new Event('change',{bubbles:true}))}else{const quick=form.querySelector('[data-quick-protocol="'+protocol+'"]');if(quick)quick.click()}const manual=document.getElementById('vlessRouteFields');if(manual)manual.hidden=true;applying=false}select.addEventListener('change',selectConnection);form.querySelectorAll('[name=access_mode]').forEach(control=>control.addEventListener('change',()=>setTimeout(()=>{if(control.value==='direct'&&control.checked)selectConnection()},0)));form.querySelectorAll('[data-sub-connection]').forEach(control=>control.addEventListener('change',()=>{}));selectConnection()})();</script>'''
