def cdn_doctor_ui(profiles, path, csrf):
    candidates = []
    for profile in profiles:
        cdn_profile = profile.get('cdn') if isinstance(profile.get('cdn'), dict) else {}
        if profile.get('protocol') != 'vless' or not cdn_profile.get('enabled'):
            continue
        provider = str(cdn_profile.get('provider', 'custom'))
        host = str(cdn_profile.get('public_host', ''))
        candidates.append((str(profile.get('id', '')), str(profile.get('name', 'VLESS')), provider, host))
    options = ''.join(
        f'<option value="{esc(uid)}">{esc(name)} · {esc(provider.title())} · {esc(host)}</option>'
        for uid, name, provider, host in candidates
    )
    if not options:
        options = '<option value="">Нет созданных VLESS-подключений через CDN</option>'
    disabled = ' disabled' if not candidates else ''
    return f'''
<section class="doctor-intro"><div><b>1 · Публичный CDN</b><span>DNS, TLS, ответы edge и кеширование</span></div><div><b>2 · Источник WPP</b><span>HTTPS, Host и контрольный маршрут Caddy</span></div><div><b>3 · XHTTP</b><span>Метод провайдера, путь и локальный inbound</span></div></section>
<section class="card"><div class="card-title"><div><h2>Диагностика и восстановление</h2><p class="muted">Проверка находит проблему, а восстановление безопасно пересобирает только локальные компоненты WPP.</p></div></div><form id="cdnDoctorForm" class="doctor-controls"><input type="hidden" name="csrf" value="{esc(csrf)}"><label>Подключение<select name="id" required{disabled}>{options}</select></label><div class="doctor-actions"><button class="primary" type="submit"{disabled}>{icon('search')}Проверить</button><button type="button" id="cdnDoctorRepair" hidden{disabled}>Исправить WPP</button></div></form><p class="muted">DNS, сертификат и правила в кабинете CDN не меняются автоматически — для них доктор покажет точную рекомендацию.</p></section>
<section class="card" id="cdnDoctorReport"><div class="empty"><div><h3>Проверка ещё не запускалась</h3><p class="muted">Результаты и рекомендации появятся здесь.</p></div></div></section>
<script>(()=>{{const form=document.getElementById('cdnDoctorForm'),report=document.getElementById('cdnDoctorReport'),repair=document.getElementById('cdnDoctorRepair'),check=form?.querySelector('button[type="submit"]');if(!form||!report||!repair||!check)return;const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[char]));const render=data=>{{const rows=data.results.map(item=>`<div class="doctor-row ${{escape(item.level)}}"><span class="doctor-state">${{item.level==='pass'?'✓':item.level==='warn'?'!':'×'}}</span><strong>${{escape(item.label)}}</strong><div class="doctor-detail">${{escape(item.detail)}}${{item.fix?`<span class="doctor-fix">Как исправить: ${{escape(item.fix)}}</span>`:''}}</div></div>`).join(''),localFailure=data.results.some(item=>['origin','xray'].includes(item.key)&&item.level==='fail'),notes=data.repair_message?`<div class="doctor-repair-note"><b>${{escape(data.repair_message)}}</b>${{(data.repair_actions||[]).map(value=>`<span>✓ ${{escape(value)}}</span>`).join('')}}${{(data.repair_warnings||[]).map(value=>`<span>! ${{escape(value)}}</span>`).join('')}}</div>`:'';repair.hidden=!localFailure;report.innerHTML=`${{notes}}<div class="doctor-summary ${{data.ok?'pass':'fail'}}"><i></i><div><b>${{data.ok?'Критических ошибок не найдено':'Найдены ошибки: '+data.failed}}</b><small>${{escape(data.provider)}} · ${{escape(data.cdn_host)}} · метод ${{escape(data.method)}}</small></div></div><div class="doctor-results">${{rows}}</div>`}};const request=async(endpoint,working)=>{{check.disabled=true;repair.disabled=true;report.innerHTML=`<div class="doctor-working">${{working}}</div>`;try{{const response=await fetch('{esc(path)}/'+endpoint,{{method:'POST',headers:{{'X-WPP-Async':'1'}},body:new URLSearchParams(new FormData(form))}});let data;try{{data=await response.json()}}catch(error){{throw new Error('Панель вернула некорректный ответ.')}}if(!response.ok||!data.results)throw new Error(data.message||'Операция не выполнена.');render(data)}}catch(error){{report.innerHTML=`<div class="note warning">${{escape(error.message)}}</div>`}}finally{{check.disabled=false;repair.disabled=false}}}};form.addEventListener('submit',event=>{{event.preventDefault();request('cdn-doctor-run','Проверяем DNS, HTTPS, CDN и Xray…')}});repair.addEventListener('click',()=>{{if(confirm('Восстановить локальные настройки Xray и Caddy? Внешние настройки CDN не изменятся.'))request('cdn-doctor-repair','Создаём резервную копию и восстанавливаем локальную часть WPP…')}})}})();</script>'''


def nodes_ui(nodes, local, connection_token, path, csrf):
    cards=[]
    for node in nodes:
        icon_flag=node_flag_image(node.get('country_code','UN'),path)
        cards.append(f'''<article class="card node-card">
<div class="node-card-head"><span class="node-flag">{icon_flag}</span><div class="node-card-name"><h2>{esc(node.get('country_name','Сервер'))}</h2><span>Страна ноды</span></div><span class="badge {'on' if node.get('enabled',True) else ''}">{'Подключена' if node.get('enabled',True) else 'Отключена'}</span></div>
<div class="node-endpoint">{icon('link')}<span>{esc(node.get('url',''))}</span></div>
<div class="node-card-meta"><div><span>Версия</span><strong>{esc(node.get('version','—'))}</strong></div><div><span>Подключения</span><strong>VLESS · Hysteria2</strong></div></div>
<form class="node-remove" method="post" action="{esc(path)}/node-action" data-confirm="Удалить ноду из этой панели?"><input type="hidden" name="csrf" value="{esc(csrf)}"><input type="hidden" name="operation" value="delete"><input type="hidden" name="id" value="{esc(node.get('id',''))}"><button class="danger">Удалить ноду</button></form></article>''')
    local_flag=node_flag_image(local.get('country_code','UN'),path)
    country_options=node_country_select(local)
    local_country=local.get('country_name','Сервер')
